"use client"

import * as React from "react"
import {
  isMotionValue,
  motion,
  useMotionValue,
  useTransform,
  type MotionValue,
} from "motion/react"

import { ringMask } from "@/lib/afterglow"
import { cn } from "@/lib/utils"

/*
 * Liquid glass: a pane that bends whatever sits behind it, like Apple's
 * Liquid Glass. The rim is a curved lens, so content near the edges is
 * pulled inward, while the flat middle stays clear.
 *
 * Refraction is an SVG displacement map used as a backdrop-filter, which only
 * Chromium supports. Other browsers get a frosted fallback with the same rim.
 */

const SAMPLES = 128
const INDEX_OF_REFRACTION = 1.5

// convex squircle: flat in the middle, rounding off toward the rim
const surface = (x: number) => Math.pow(1 - Math.pow(1 - x, 4), 0.25)

// how far a straight-down ray is bent sideways at each point across the rim
function rimProfile(bezel: number) {
  const profile = new Float32Array(SAMPLES)
  for (let i = 0; i < SAMPLES; i++) {
    const x = i / (SAMPLES - 1)
    const a = Math.max(x - 0.001, 0)
    const b = Math.min(x + 0.001, 1)
    const slope = (surface(b) - surface(a)) / (b - a)
    const incident = Math.atan(slope)
    const refracted = Math.asin(Math.sin(incident) / INDEX_OF_REFRACTION)
    const thickness = bezel * (0.25 + surface(x))
    profile[i] = thickness * Math.tan(incident - refracted)
  }
  return profile
}

type DisplacementMap = { url: string; scale: number }
const maps = new Map<string, DisplacementMap>()

function displacementMap(
  width: number,
  height: number,
  radius: number,
  bezel: number,
  magnify: number
): DisplacementMap {
  const key = [width, height, radius, bezel, magnify].join(":")
  const cached = maps.get(key)
  if (cached) return cached

  const profile = rimProfile(bezel)
  const dx = new Float32Array(width * height)
  const dy = new Float32Array(width * height)
  let max = 0

  for (let j = 0; j < height; j++) {
    for (let i = 0; i < width; i++) {
      // signed distance to a rounded rectangle, and the outward normal
      const px = i + 0.5 - width / 2
      const py = j + 0.5 - height / 2
      const qx = Math.abs(px) - width / 2 + radius
      const qy = Math.abs(py) - height / 2 + radius
      const inside =
        -(Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) +
          Math.min(Math.max(qx, qy), 0) -
          radius)
      let nx = 0
      let ny = 0
      if (qx > 0 && qy > 0) {
        const length = Math.hypot(qx, qy) || 1
        nx = (qx / length) * Math.sign(px)
        ny = (qy / length) * Math.sign(py)
      } else if (qx > qy) nx = Math.sign(px)
      else ny = Math.sign(py)

      let x = -px * magnify
      let y = -py * magnify
      if (inside >= 0 && inside < bezel) {
        // sample inward, so the rim shows what's just inside the edge
        const shift = profile[Math.round((inside / bezel) * (SAMPLES - 1))]
        x -= nx * shift
        y -= ny * shift
      }
      const k = j * width + i
      dx[k] = x
      dy[k] = y
      max = Math.max(max, Math.abs(x), Math.abs(y))
    }
  }

  const canvas = document.createElement("canvas")
  canvas.width = width
  canvas.height = height
  const context = canvas.getContext("2d")
  if (!context) return { url: "", scale: 0 }
  const image = context.createImageData(width, height)
  for (let k = 0; k < width * height; k++) {
    // 128 is "no shift"; red moves along x, green along y
    image.data[k * 4] = 128 + (dx[k] / (max || 1)) * 127
    image.data[k * 4 + 1] = 128 + (dy[k] / (max || 1)) * 127
    image.data[k * 4 + 2] = 128
    image.data[k * 4 + 3] = 255
  }
  context.putImageData(image, 0, 0)

  const map = { url: canvas.toDataURL(), scale: max * 2 }
  if (maps.size > 48) maps.delete(maps.keys().next().value!)
  maps.set(key, map)
  return map
}

// only Chromium can use an SVG filter as a backdrop-filter
function canRefract() {
  const nav = navigator as Navigator & {
    userAgentData?: { brands: { brand: string }[] }
  }
  if (nav.userAgentData) {
    return nav.userAgentData.brands.some((b) => b.brand === "Chromium")
  }
  return /Chrome\/\d+/.test(nav.userAgent) && !/Firefox|FxiOS/.test(nav.userAgent)
}

const noopSubscribe = () => () => {}

function useCanRefract() {
  return React.useSyncExternalStore(noopSubscribe, canRefract, () => false)
}

type LiquidGlassProps = React.ComponentProps<"div"> & {
  /** width of the curved rim in px, defaults to the corner radius (max 24) */
  bezel?: number
  /** 0 is flat glass, 1 is the full lens; pass a motion value to animate it */
  refraction?: number | MotionValue<number>
  /** zooms the middle like a magnifier, 0 to 0.3 */
  magnify?: number
  /** blur behind the glass in px */
  frost?: number
  /** a color mixed over the glass, e.g. for a tinted primary button */
  tint?: string
  /**
   * fades the whole pane in and out. Never fade a parent of liquid glass
   * instead: an ancestor with opacity cuts the glass off from what's behind it.
   */
  presence?: number | MotionValue<number>
}

function LiquidGlass({
  bezel,
  refraction = 1,
  magnify = 0,
  frost = 1,
  tint,
  presence = 1,
  className,
  children,
  ...props
}: LiquidGlassProps) {
  const ref = React.useRef<HTMLDivElement>(null)
  const displaceRef = React.useRef<SVGFEDisplacementMapElement>(null)
  const id = `liquid-${React.useId().replace(/[^a-zA-Z0-9_-]/g, "")}`
  const refract = useCanRefract()
  const [shape, setShape] = React.useState<{ w: number; h: number; r: number }>()
  // the scale last written to the filter, so a no-op resize can put it back
  const applied = React.useRef(0)

  React.useEffect(() => {
    const node = ref.current
    if (!node || !refract) return
    const measure = () => {
      const w = Math.round(node.offsetWidth)
      const h = Math.round(node.offsetHeight)
      const raw = getComputedStyle(node).borderTopLeftRadius
      const value = parseFloat(raw) || 0
      const r = Math.round(
        Math.min(raw.endsWith("%") ? (value / 100) * Math.min(w, h) : value, w / 2, h / 2)
      )
      setShape((prev) => {
        if (prev?.w === w && prev.h === h && prev.r === r) {
          displaceRef.current?.setAttribute("scale", String(applied.current))
          return prev
        }
        return { w, h, r }
      })
    }
    // measure right away, then wait for resizing to settle before rebuilding the map
    let first = true
    let frame = 0
    let timer = 0
    const observer = new ResizeObserver(() => {
      if (first) {
        first = false
        measure()
        return
      }
      // until the new map is ready, the old one would bend the wrong pixels
      displaceRef.current?.setAttribute("scale", "0")
      window.clearTimeout(timer)
      timer = window.setTimeout(() => {
        frame = requestAnimationFrame(measure)
      }, 100)
    })
    observer.observe(node)
    return () => {
      observer.disconnect()
      window.clearTimeout(timer)
      cancelAnimationFrame(frame)
    }
  }, [refract])

  const map = React.useMemo(() => {
    if (!refract || !shape || shape.w < 2 || shape.h < 2) return undefined
    const rim = Math.max(1, Math.min(bezel ?? Math.min(shape.r, 24), shape.w / 2, shape.h / 2))
    return displacementMap(shape.w, shape.h, shape.r, Math.round(rim), magnify)
  }, [bezel, magnify, refract, shape])

  // animate refraction by scaling the filter, without rebuilding the map
  React.useEffect(() => {
    if (!map) return
    const apply = (v: number) => {
      applied.current = map.scale * v
      displaceRef.current?.setAttribute("scale", String(applied.current))
    }
    if (typeof refraction === "number") {
      apply(refraction)
      return
    }
    apply(refraction.get())
    return refraction.on("change", apply)
  }, [map, refraction])

  const ownPresence = useMotionValue(isMotionValue(presence) ? 1 : presence)
  const visible = isMotionValue(presence) ? presence : ownPresence
  React.useEffect(() => {
    if (!isMotionValue(presence)) ownPresence.set(presence)
  }, [ownPresence, presence])
  const rimOpacity = useTransform(visible, (v) => v * 0.95)

  const strength = isMotionValue(refraction) ? refraction.get() : refraction
  const backdrop = map
    ? `url(#${id})`
    : `blur(${Math.max(frost, 10)}px) saturate(1.6)`

  return (
    <div
      ref={ref}
      data-slot="liquid-glass"
      // no isolation here: an isolated parent cuts the glass off from the scene
      // behind it in Chrome. Layers stack in source order, and direct children
      // are made relative so they sit on top (wrap an absolute child to keep it).
      className={cn("relative [&>:where(:not([data-glass-layer]))]:relative", className)}
      {...props}
    >
      {map && (
        <svg data-glass-layer aria-hidden width="0" height="0" className="pointer-events-none absolute">
          <filter id={id} colorInterpolationFilters="sRGB">
            <feGaussianBlur in="SourceGraphic" stdDeviation={frost} result="frost" />
            <feImage
              href={map.url}
              x="0"
              y="0"
              width={shape?.w}
              height={shape?.h}
              preserveAspectRatio="none"
              result="map"
            />
            <feDisplacementMap
              ref={displaceRef}
              in="frost"
              in2="map"
              scale={map.scale * strength}
              xChannelSelector="R"
              yChannelSelector="G"
              result="bent"
            />
            {/* glass makes what's behind it a little brighter and more vivid */}
            <feColorMatrix in="bent" type="saturate" values="1.45" result="vivid" />
            <feComponentTransfer in="vivid">
              <feFuncR type="linear" slope="1.05" />
              <feFuncG type="linear" slope="1.05" />
              <feFuncB type="linear" slope="1.05" />
            </feComponentTransfer>
          </filter>
        </svg>
      )}
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[0_10px_30px_-10px_var(--liquid-shadow),0_2px_8px_-2px_var(--liquid-shadow)]"
        style={{ opacity: visible }}
      />
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit]"
        style={{
          backdropFilter: backdrop,
          WebkitBackdropFilter: backdrop,
          opacity: visible,
        }}
      />
      {/* tint, heavier when there's no refraction so text stays legible */}
      <motion.div
        data-glass-layer
        aria-hidden
        className={cn(
          "pointer-events-none absolute inset-0 rounded-[inherit] bg-(--liquid-tint)",
          !map && "bg-(--liquid-fallback)"
        )}
        style={tint ? { background: tint, opacity: visible } : { opacity: visible }}
      />
      {/* volume: light gathers inside the top edge, shade settles along the bottom */}
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[inset_0_1px_16px_-4px_var(--liquid-glow),inset_0_-12px_20px_-14px_var(--liquid-shade)]"
        style={{ opacity: visible }}
      />
      {/* rim light: bright where the light comes from (top left), softer opposite */}
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[inset_0_0_0_0.5px_var(--liquid-edge),inset_1px_1.5px_1px_-1px_var(--liquid-rim),inset_-1px_-1.5px_1px_-1px_color-mix(in_oklch,var(--liquid-rim)_45%,transparent)]"
        style={{ opacity: visible }}
      />
      <motion.div
        data-glass-layer
        aria-hidden
        className="pointer-events-none absolute inset-0 rounded-[inherit] p-px"
        style={{
          ...ringMask,
          background:
            "conic-gradient(from 300deg, var(--liquid-rim), transparent 70deg, transparent 110deg, color-mix(in oklch, var(--liquid-rim) 55%, transparent) 180deg, transparent 250deg, transparent 290deg, var(--liquid-rim))",
          opacity: rimOpacity,
        }}
      />
      {children}
    </div>
  )
}

export { LiquidGlass, useCanRefract, type LiquidGlassProps }

"use client"

import * as React from "react"
import { Eye, EyeOff, Fingerprint, KeyRound, Loader2 } from "lucide-react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"

/* Shared pieces for the auth blocks: brand marks, provider buttons, fields,
   a divider and a small hook that runs a submit with loading and error states. */

function GoogleMark({ mono = false, ...props }: React.ComponentProps<"svg"> & { mono?: boolean }) {
  // mono draws the G in the current text color, for quiet monochrome buttons
  const fill = (color: string) => (mono ? "currentColor" : color)
  return (
    <svg viewBox="0 0 24 24" aria-hidden {...props}>
      <path fill={fill("#4285F4")} d="M23.5 12.27c0-.85-.08-1.67-.22-2.45H12v4.64h6.45a5.52 5.52 0 0 1-2.4 3.62v3h3.88c2.27-2.09 3.57-5.17 3.57-8.81Z" />
      <path fill={fill("#34A853")} d="M12 24c3.24 0 5.96-1.07 7.94-2.92l-3.88-3c-1.07.72-2.45 1.15-4.06 1.15-3.12 0-5.77-2.11-6.71-4.95H1.28v3.1A12 12 0 0 0 12 24Z" />
      <path fill={fill("#FBBC05")} d="M5.29 14.28a7.2 7.2 0 0 1 0-4.56v-3.1H1.28a12 12 0 0 0 0 10.76l4.01-3.1Z" />
      <path fill={fill("#EA4335")} d="M12 4.77c1.76 0 3.34.61 4.59 1.8l3.44-3.44A11.97 11.97 0 0 0 12 0 12 12 0 0 0 1.28 6.62l4.01 3.1C6.23 6.88 8.88 4.77 12 4.77Z" />
    </svg>
  )
}

// the afterglow mark: a sun setting on the horizon, centered in its 24px box
function AfterglowMark(props: React.ComponentProps<"svg">) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden {...props}>
      <path d="M5.5 12a6.5 6.5 0 0 1 13 0Z" fill="currentColor" />
      <path d="M3 15h18M7.5 18h9" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
    </svg>
  )
}

function GitHubMark(props: React.ComponentProps<"svg">) {
  return (
    <svg viewBox="0 0 16 16" aria-hidden fill="currentColor" {...props}>
      <path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.013 8.013 0 0 0 16 8c0-4.42-3.58-8-8-8Z" />
    </svg>
  )
}

const providers = {
  google: { label: "Google", icon: <GoogleMark /> },
  github: { label: "GitHub", icon: <GitHubMark /> },
  sso: { label: "SSO", icon: <KeyRound /> },
  passkey: { label: "passkey", icon: <Fingerprint /> },
}

type Provider = keyof typeof providers

type ProviderButtonProps = Omit<React.ComponentProps<"button">, "children"> & {
  provider: Provider
  /** "Continue with", "Log in with"… */
  verb?: string
  /** a small "Last used" badge in the corner */
  lastUsed?: boolean
}

function ProviderButton({
  provider,
  verb = "Continue with",
  lastUsed,
  className,
  type = "button",
  ...props
}: ProviderButtonProps) {
  const { label, icon } = providers[provider]
  return (
    <button
      type={type}
      className={cn(
        "relative inline-flex h-10 w-full cursor-pointer items-center justify-center gap-2.5 rounded-lg border bg-background/60 px-4 text-sm font-medium transition-[background-color,scale] duration-150 ease-out outline-none hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring enabled:active:scale-[0.98] disabled:opacity-50 [&_svg]:size-4 [&_svg]:shrink-0",
        className
      )}
      {...props}
    >
      {icon}
      <span>{verb ? `${verb} ${label}` : label}</span>
      {lastUsed && (
        <span className="absolute -top-2 right-2 rounded-full border bg-card px-1.5 py-px text-[10px] font-medium text-muted-foreground">
          Last used
        </span>
      )}
    </button>
  )
}

function Divider({ children = "or", className }: { children?: React.ReactNode; className?: string }) {
  return (
    <div className={cn("flex items-center gap-3 text-xs text-muted-foreground", className)}>
      <span className="h-px flex-1 bg-border" />
      {children}
      <span className="h-px flex-1 bg-border" />
    </div>
  )
}

type FieldProps = Omit<React.ComponentProps<"input">, "size"> & {
  label: string
  /** shown under the field and announced by screen readers */
  error?: string
  /** a link or action placed at the end of the label row, e.g. "Forgot?" */
  aside?: React.ReactNode
  /** classes for the input's box, so each theme can style it */
  boxClassName?: string
  labelClassName?: string
}

function Field({
  label,
  error,
  aside,
  type = "text",
  className,
  boxClassName,
  labelClassName,
  id,
  ...props
}: FieldProps) {
  const autoId = React.useId()
  const inputId = id ?? autoId
  const errorId = `${inputId}-error`
  const [reveal, setReveal] = React.useState(false)
  const password = type === "password"

  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      <div className="flex items-center justify-between">
        <label htmlFor={inputId} className={cn("text-sm font-medium", labelClassName)}>
          {label}
        </label>
        {aside}
      </div>
      <div
        className={cn(
          "flex h-10 items-center rounded-lg border bg-background/60 px-3 transition-[border-color,box-shadow] duration-150 focus-within:border-foreground/40 focus-within:ring-3 focus-within:ring-foreground/10",
          error && "border-glow-2/70 focus-within:border-glow-2 focus-within:ring-glow-2/15",
          boxClassName
        )}
      >
        <input
          id={inputId}
          type={password && reveal ? "text" : type}
          aria-invalid={error ? true : undefined}
          aria-describedby={error ? errorId : undefined}
          className="h-full min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground/70"
          {...props}
        />
        {password && (
          <button
            type="button"
            aria-label={reveal ? "Hide password" : "Show password"}
            aria-pressed={reveal}
            onClick={() => setReveal((v) => !v)}
            className="-mr-1 grid size-7 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60 [&_svg]:size-4"
          >
            {reveal ? <EyeOff /> : <Eye />}
          </button>
        )}
      </div>
      <AnimatePresence initial={false}>
        {error && (
          <motion.p
            id={errorId}
            className="text-xs text-glow-2"
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.15 }}
          >
            {error}
          </motion.p>
        )}
      </AnimatePresence>
    </div>
  )
}

type Status = "idle" | "loading" | "done"

/**
 * Runs an async submit with loading and error states. The block calls
 * `run(values)`; your `onSubmit` does the real work and throws to show an error.
 */
function useSubmit<T>(onSubmit?: (values: T) => Promise<void> | void) {
  const [status, setStatus] = React.useState<Status>("idle")
  const [error, setError] = React.useState<string>()

  async function run(values: T) {
    setError(undefined)
    setStatus("loading")
    try {
      await onSubmit?.(values)
      setStatus("done")
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Something went wrong. Try again.")
      setStatus("idle")
    }
  }

  return { status, error, setError, run, reset: () => setStatus("idle") }
}

// a label that swaps to a spinner while the form is busy
function SubmitLabel({ loading, children }: { loading: boolean; children: React.ReactNode }) {
  const reduceMotion = useReducedMotion()
  return (
    <span className="grid place-items-center">
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          key={loading ? "loading" : "label"}
          className="col-start-1 row-start-1 inline-flex items-center gap-2"
          initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.25, filter: "blur(4px)" }}
          animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
          exit={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.25, filter: "blur(4px)" }}
          transition={{ type: "spring", duration: 0.3, bounce: 0 }}
        >
          {loading ? <Loader2 className="size-4 animate-spin" aria-label="Loading" /> : children}
        </motion.span>
      </AnimatePresence>
    </span>
  )
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

function checkEmail(value: string) {
  if (!value.trim()) return "Enter your email address."
  if (!EMAIL.test(value.trim())) return "That doesn't look like an email address."
  return undefined
}

export {
  AfterglowMark,
  Divider,
  Field,
  GitHubMark,
  GoogleMark,
  ProviderButton,
  SubmitLabel,
  checkEmail,
  useSubmit,
  type FieldProps,
  type Provider,
  type ProviderButtonProps,
}

import type { CSSProperties } from "react"
import type { TargetAndTransition, Transition } from "motion/react"

// shared spring presets, every component picks from these
export const springs = {
  snappy: { stiffness: 520, damping: 34, mass: 0.6 },
  soft: { stiffness: 260, damping: 26, mass: 0.8 },
  glide: { stiffness: 120, damping: 20, mass: 1 },
} as const

export type SpringName = keyof typeof springs

export function spring(name: SpringName): Transition {
  return { type: "spring", ...springs[name] }
}

// how a glow fades once its source moves away: slow, with a long tail
export const afterglow = {
  linger: 0.9,
  ease: [0.22, 1, 0.36, 1],
} as const satisfies { linger: number; ease: Transition["ease"] }

// paints only the padding ring of an element, used for glowing borders
export const ringMask: CSSProperties = {
  WebkitMask:
    "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
  WebkitMaskComposite: "xor",
  mask: "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
  maskComposite: "exclude",
}

// small icon gestures, played when a control is pressed or selected
export const iconGestures = {
  pop: { scale: [1, 1.2, 1] },
  ring: { rotate: [0, -18, 14, -9, 4, 0], scale: [1, 1.12, 1] },
  // a gear looks the same after half a turn, so it can rest there and snap back unseen
  turn: { rotate: [0, 180], scale: [1, 1.12, 1] },
  hop: { y: [0, -3, 0], scale: [1, 1.1, 1] },
  nudge: { x: [0, 2.5, 0], scale: [1, 1.1, 1] },
} satisfies Record<string, TargetAndTransition>

export type IconGesture = keyof typeof iconGestures

// leaving a gesture is instant: every gesture already ends at, or looks like, its resting pose
export const iconRest: TargetAndTransition = { scale: 1, rotate: 0, x: 0, y: 0, transition: { duration: 0 } }
